            const old_len = self.len;
            _ = try self.resize((old_len + n));
            _ = @memset(self.slice()[old_len..self.len], value);
    }

pub fn appendNTimesAssumeCapacity(self: *@This(), value: T, n: usize) void {
            const old_len: usize = self.len;
            const new_len: usize = (old_len + (if (comptime @typeInfo(@TypeOf(n)) == .@"enum") cp_cast_int(usize, @intFromEnum(n)) else cp_cast_int(usize, n)));
            self.len = @intCast(new_len);
            _ = assert((self.len <= buffer_capacity));
            _ = @memset(self.slice()[old_len..self.len], value);
    }

pub fn writer(self: *@This()) Writer {
            return .{ .context = self };
    }

pub fn appendWrite(self: *@This(), m: []const u8) Overflow!usize {
            _ = try self.appendSlice(m);
            return m.len;
    }
    const Self = @This();
    const Length = std.math.ByteAlignedInt(std.math.IntFittingRange(0, buffer_capacity));
    pub const Buffer = @FieldType(Self, "buffer");
    pub const Overflow = error{Overflow};
    pub const Writer = (if ((T != u8)) @compileError(((("The Writer interface is only defined for BoundedArray(u8, ...) " ++ "but the given type is BoundedArray(") ++ @typeName(T)) ++ ", ...)")) else std.io.GenericWriter(*Self, Overflow, appendWrite));
};
}
